+func validateOCIRepository(repository string) error {
+	scheme, reference, explicit := strings.Cut(repository, "://")
+	if explicit {
+		// Reject unsupported schemes before parsing the registry reference so
+		// the configuration error identifies the unsupported protocol.
+		switch scheme {
+		case "http", "https", "flipt":
+		default:
+			return fmt.Errorf("unexpected repository scheme: %q should be one of [http|https|flipt]", scheme)
+		}
+		if scheme == "flipt" && !strings.Contains(reference, "/") {
+			reference = "local/" + reference
+		}
+	} else {
+		reference = repository
+		if !strings.Contains(reference, "/") && strings.Contains(reference, ":") {
+			reference = "local/" + reference
+		}
+	}
+
+	ref, err := registry.ParseReference(reference)
+	if err != nil {
+		return err
+	}
+	if explicit && scheme == "flipt" && ref.Registry != "local" {
+		return fmt.Errorf("unexpected local reference: %q", ref)
+	}
+	return nil
+}
+
+// DefaultBundleDir returns the default directory for OCI bundles, creating it if needed.
+func DefaultBundleDir() (string, error) {
+	dir, err := Dir()
+	if err != nil {
+		return "", err
+	}
+	bundlesDir := filepath.Join(dir, "bundles")
+	if err := os.MkdirAll(bundlesDir, 0755); err != nil {
+		return "", fmt.Errorf("creating bundles directory: %w", err)
+	}
+	return bundlesDir, nil
+}
