import (
	"os"
	"path/filepath"
	"testing"
)

func TestDefaultBundleDir(t *testing.T) {
	configRoot := t.TempDir()
	t.Setenv("XDG_CONFIG_HOME", configRoot)

	dir, err := DefaultBundleDir()
	if err != nil {
		t.Fatal(err)
	}
	if want := filepath.Join(configRoot, "flipt", "bundles"); dir != want {
		t.Fatalf("bundle directory = %q, want %q", dir, want)
	}
	info, err := os.Stat(dir)
	if err != nil {
		t.Fatal(err)
	}
	if !info.IsDir() {
		t.Fatalf("bundle path %q is not a directory", dir)
	}
}
